#include<bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef unsigned long long ull;
typedef pair<int,int> pii;
typedef pair<ll,ll> pll;
typedef vector<int> vi;
typedef vector<ll> vll;

const int MAXN = 500 + 100;

ll mod;

struct Mint {
    ll v;
    Mint() : v(0) {}
    Mint(ll x) { v = x >= 0 ? x % mod : (x % mod + mod); }
    Mint pow(ll e) const {
        if(!e) return 1;
        Mint half = pow(e/2);
        return (e&1) ? half * half * (*this) : half * half;
    }
    Mint inverse() const {
        static unordered_map<ll,ll> cache;
        if(cache.count(v)) return cache[v];
        if(cache.size() < 100000) return Mint(cache[v] = pow(mod-2).v);
        return pow(mod-2);
    }
    Mint operator+(const Mint &o) const { return (v + o.v) % mod; }
    Mint operator-(const Mint &o) const { return (v - o.v + mod) % mod; }
    Mint operator*(const Mint &o) const { return (v * o.v) % mod; }
    Mint operator/(const Mint &o) const { return *this * o.inverse(); }
    Mint &operator+=(const Mint &o) { v = (v + o.v) % mod; return *this; }
    Mint &operator-=(const Mint &o) { v = (v - o.v + mod) % mod; return *this; }
    Mint &operator*=(const Mint &o) { v = (v * o.v) % mod; return *this; }
    Mint &operator/=(const Mint &o) { v = (v * o.inverse().v) % mod; return *this; }
    bool operator==(const Mint &o) const { return v == o.v; }
    bool operator!=(const Mint &o) const { return v != o.v; }
};

vector<vector<Mint>> comb;
void gen_comb(int n) {
    comb.assign(n+1, vector<Mint>(n+1));
    for(int i=0; i<=n; ++i) {
        comb[i][0] = comb[i][i] = 1;
        for(int j=1; j<i; ++j) comb[i][j] = comb[i-1][j-1] + comb[i-1][j];
    }
}

vector<Mint> a(MAXN,0), c(MAXN,0);
vector<vector<array<Mint,2>>> dp(MAXN, vector<array<Mint,2>>(MAXN));
vector<vector<array<Mint,2>>> dpc(MAXN, vector<array<Mint,2>>(MAXN));

ll s1(ll l, ll r) {
    if(l>r) return 0;
    return (l+r)*(r-l+1)/2;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n,m;
    cin>>n>>m>>mod;
    gen_comb(MAXN-1);

    a[0]=Mint(0); c[0]=Mint(1);
    a[1]=Mint(0); c[1]=Mint(2);
    for(int i=2; i<=m; ++i) {
        Mint tmp=0, tmpc=0;
        for(int l=0; l<i; ++l) {
            ll r = i-1-l;
            Mint term1 = c[l] * c[r] * (s1(1,l) + s1(1,r)) * comb[i-1][l];
            Mint term2 = (a[l] * c[r] + a[r] * c[l]) * comb[i-1][l] * (i+1);
            tmp += term1 + term2;
            tmpc += c[l] * c[r] * (i+1) * comb[i-1][l];
        }
        a[i] = tmp;
        c[i] = tmpc;
    }

    dpc[0][0][0] = 1;
    for(int i=1; i<=n; ++i) {
        for(int j=0; j<=m; ++j) {
            if(j>i) continue;
            dpc[i][j][0] = dpc[i-1][j][0] + dpc[i-1][j][1];
            for(int k=1; k<=j; ++k) {
                dpc[i][j][1] += c[k] * comb[j][k] * dpc[i-k][j-k][0];
            }
        }
    }

    for(int i=1; i<=n; ++i) {
        for(int j=0; j<=m; ++j) {
            if(j>i) continue;
            dp[i][j][0] = dp[i-1][j][0] + dp[i-1][j][1];
            for(int k=1; k<=j; ++k) {
                dp[i][j][1] += a[k] * comb[j][k] * dpc[i-k][j-k][0] + dp[i-k][j-k][0] * c[k] * comb[j][k];
            }
        }
    }

    cout << (dp[n][m][0] + dp[n][m][1]).v << endl;
    return 0;
}
